class Solution {
public:
    int maxEnvelopes(vector<vector<int>>& envelopes) {
        sort(envelopes.begin(),envelopes.end(),[](auto &a,auto &b){
            if(a[0]==b[0]) return a[1]>b[1];
            return a[0]<b[0];
        });

        //lis on height
        vector<int>tails;
        tails.push_back(envelopes[0][1]);
        for(auto e:envelopes){
            int x=e[1];
            auto it=lower_bound(tails.begin(),tails.end(),x);
            if(it==tails.end()){
                tails.push_back(x);
            }
            else{
                *it=x;
            }
        }
        return tails.size();
    }
};

class Solution {
public:
    const int INF=1e9;
    int minCost(vector<vector<int>>& grid) {
        vector<vector<int>>dist,vis;
        dist.resize(grid.size(),vector<int>(grid[0].size(),INF));
        vis.resize(grid.size(),vector<int>(grid[0].size(),0));
        priority_queue<pair<int,pair<int,int>>>pq;//{-dist,node}
        pq.push({0,{0,0}});
        int dx[4]={0,0,1,-1};
        int dy[4]={1,-1,0,0};
        while(!pq.empty()){
            auto x=pq.top();
            pq.pop();
            int i,j;
            i=x.second.first;
            j=x.second.second;
            vis[i][j]=1;
            dist[0][0]=0;
            for(int dir=0;dir<4;dir++){
                int nx=i+dx[dir];
                int ny=j+dy[dir];
                if(nx>=0&&nx<grid.size()&&ny>=0&&ny<grid[0].size()){
                    if(!vis[nx][ny]){
                        int wt=0;
                        if(grid[i][j]!=dir+1)wt=1;
                        if(dist[nx][ny]>dist[i][j]+wt){
                            dist[nx][ny]=dist[i][j]+wt;
                            pq.push({-1*dist[nx][ny],{nx,ny}});
                        }

                    }
                }
            }
        }
        return dist[grid.size()-1][grid[0].size()-1];
    }
};

class Solution {
public:
    vector<int>indeg;

    void kahn(vector<vector<int>>&adj,vector<int>&time,int n,vector<int>&dp){
        queue<int>q;
        for(int i=0;i<n;i++)if(indeg[i]==0)q.push(i);

        while(!q.empty()){
                int node=q.front();
                q.pop();
                for(auto v:adj[node]){
                    dp[v]=max(dp[v],time[v]+dp[node]);
                    indeg[v]--;
                    if(indeg[v]==0)q.push(v);
                }
        }
    }
    int minimumTime(int n, vector<vector<int>>& relations, vector<int>& time) {
        indeg.resize(n,0);
        vector<vector<int>>adj(n);
        vector<int>dp=time;
        for(auto r:relations){
            adj[r[0]-1].push_back(r[1]-1);
            indeg[r[1]-1]++;
        }
        kahn(adj,time,n,dp);
        int ans=0;
        for(int i=0;i<n;i++)ans=max(ans,dp[i]);
        return ans;
    }
};

class Solution {
public:
    int numBusesToDestination(vector<vector<int>>& routes, int source, int target) {
        unordered_map<int,vector<int>>mp;
        for(int i=0;i<routes.size();i++){
            for(int j=0;j<routes[i].size();j++){
                mp[routes[i][j]].push_back(i);
            }
        }
        int n=routes.size();
        queue<int> q;
        unordered_set<int> visStp;
        vector<bool> visB(n, 0);

        q.push(source);
        visStp.insert(source);
        int busses=0;
        while(!q.empty()){
            int sz=q.size();

            while(sz--){
                int stp=q.front();
                if(stp==target)return busses;
                q.pop();
                for(auto bus:mp[stp]){

                    if(!visB[bus]){
                        visB[bus]=1;
                        for(auto neigh:routes[bus]){
                            if(!visStp.count(neigh)){
                                visStp.insert(neigh);
                                q.push(neigh);
                            }
                        }
                    }
                }
            }
            busses++;
        }
        return -1;
    }
};

class Solution {
public:
    vector<vector<int>>vis;
    int dx[4]={-1,1,0,0};
    int dy[4]={0,0,-1,1};

    int rec(int x,int y,vector<vector<int>>& matrix){
        //base case
        //if() return 0;

        //cache check
        if(vis[x][y]!=-1){
            return vis[x][y];
        }
        //transition
        int ans=1;
        for(int i=0;i<4;i++){
            int nx=x+dx[i];
            int ny=y+dy[i];

            if(nx>=0&&nx<vis.size()&&ny>=0&&ny<vis[0].size()){
                if(matrix[nx][ny]>matrix[x][y]){
                    ans=max(1+rec(nx,ny,matrix),ans);
                }
            }
        }
        vis[x][y]=ans;

        return ans;
    }
    int longestIncreasingPath(vector<vector<int>>& matrix) {
        vis.resize(matrix.size(),vector<int>(matrix[0].size(),-1));
        int ans=0;
        for(int i=0;i<matrix.size();i++){
            for(int j=0;j<matrix[0].size();j++){
                if(vis[i][j]==-1){
                  ans=max(ans,rec(i,j,matrix));
                }
            }
        }
    return ans;
    }
};

class Solution {
    struct Node {
        Node* child[26];
        bool isEnd;
        string word;

        Node() {
            for (int i = 0; i < 26; i++) {
                child[i] = nullptr;
            }
            isEnd = false;
            word = "";
        }
    };

    Node* root = new Node();
    vector<string> ans;
    int m, n;

    void insert(string& word) {
        Node* cur = root;

        for (int i = 0; i < word.size(); i++) {
            int idx = word[i] - 'a';

            if (cur->child[idx] == nullptr) {
                cur->child[idx] = new Node();
            }

            cur = cur->child[idx];
        }

        cur->isEnd = true;
        cur->word = word;
    }

    void dfs(vector<vector<char>>& board, int r, int c, Node* node) {
        char ch = board[r][c];
        int idx = ch - 'a';

        Node* next = node->child[idx];

        if (next == nullptr) return;

        if (next->isEnd) {
            ans.push_back(next->word);
            next->isEnd = false;
        }

        board[r][c] = '#';

        int dr[] = {-1, 1, 0, 0};
        int dc[] = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            if (nr >= 0 && nr < m &&
                nc >= 0 && nc < n &&
                board[nr][nc] != '#') {
                dfs(board, nr, nc, next);
            }
        }

        board[r][c] = ch;
    }

public:
    vector<string> findWords(vector<vector<char>>& board,
                             vector<string>& words) {
        m = board.size();
        n = board[0].size();

        for (string& word : words) {
            insert(word);
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                dfs(board, i, j, root);
            }
        }

        return ans;
    }
};

class WordDictionary {
    struct Node{
        Node* child[26];
        bool isEnd;

        Node(){
            for(int i=0;i<26;i++){
                child[i]=nullptr;
            }
            isEnd=false;
        }
    };

    Node* root;

    bool dfs(Node* node,string& word,int idx){
        if(idx==word.size()) return node->isEnd;

        if(word[idx]=='.'){
            for(int i=0;i<26;i++){
                if(node->child[i]&&dfs(node->child[i],word,idx+1))
                    return true;
            }
        }
        else{
            if(node->child[word[idx]-'a']==nullptr)return false;
            else if(dfs(node->child[word[idx]-'a'],word,idx+1))
                return true;
        }
        return false;
    }
public:
    WordDictionary() {
        root=new Node;
    }

    void addWord(string word) {
        Node* cur=root;
        for(int i=0;i<word.size();i++){
            if(!cur->child[word[i]-'a']){
                cur->child[word[i]-'a']=new Node();
            }
            //in else case akso cur moves frwrd
            cur=cur->child[word[i]-'a'];
        }
        cur->isEnd=true;
    }

    bool search(string word) {
        return dfs(root,word,0);
    }
};

