/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        ListNode dhead(0,head);
        ListNode* gprev=&dhead;

        while(true){
            ListNode* knode=gprev;
            for(int i=0;i<k && knode!=nullptr;i++){
                knode=knode->next;
            }
            if(knode==nullptr)break;

            ListNode* gnext=knode->next;
            ListNode* prev=gnext;
            ListNode* curr=gprev->next;

            while(curr!=gnext){
                ListNode* nextnode=curr->next;
                curr->next=prev;
                prev=curr;
                curr=nextnode;
            }
            ListNode* temp=gprev->next;
            gprev->next=knode;
            gprev=temp;
        }
        return dhead.next;
    }
};

class Solution {
public:
    int firstMissingPositive(vector<int>& nums) {
        int n=nums.size();
        for(int i=0;i<n;i++){
            while(nums[i]>0&&nums[i]<=n && nums[i]!=i+1 && nums[nums[i]-1]!=nums[i]){
                swap(nums[i],nums[nums[i]-1]);
            }
        }
        for(int i=0;i<n;i++){
            if(nums[i]!=i+1){
                return i+1;
            }
        }
        return n+1;
    }
};

class Solution {
public:
    string minWindow(string s, string t) {
        if (t.empty() || s.size() < t.size()) return "";

        vector<int> freq(128, 0);

        for (char c : t) freq[c]++;

        int l = 0, start = 0;
        int required = t.size();
        int best = INT_MAX;

        for (int r = 0; r < s.size(); r++) {
            if (freq[s[r]] > 0) required--;
            freq[s[r]]--;

            while (required == 0) {
                if (r - l + 1 < best) {
                    best = r - l + 1;
                    start = l;
                }
                freq[s[l]]++;
                if (freq[s[l]] > 0) required++;
                l++;
            }
        }

        return best == INT_MAX ? "" : s.substr(start, best);
    }
};

