class Solution {
public:
    bool check(int i, int n, int m, vector<int>& nums1, vector<int>& nums2) {
        int j = (m + n + 1) / 2 - i;

        int Aleft  = (i == 0) ? INT_MIN : nums1[i - 1];
        int Aright = (i == m) ? INT_MAX : nums1[i];

        int Bleft  = (j == 0) ? INT_MIN : nums2[j - 1];
        int Bright = (j == n) ? INT_MAX : nums2[j];

        if (Aleft <= Bright && Bleft <= Aright) {
            return 1;
        }

        return 0;
    }

    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        if (nums1.size() > nums2.size()) {
            swap(nums1, nums2);
        }

        int m = nums1.size();
        int n = nums2.size();

        int l = 0;
        int r = m;

        while (l <= r) {
            int i = l + (r - l) / 2;
            int j = (m + n + 1) / 2 - i;

            int Aleft  = (i == 0) ? INT_MIN : nums1[i - 1];
            int Aright = (i == m) ? INT_MAX : nums1[i];

            int Bleft  = (j == 0) ? INT_MIN : nums2[j - 1];
            int Bright = (j == n) ? INT_MAX : nums2[j];
            if (check(i, n, m, nums1, nums2)) {
                if ((n + m) % 2 == 0) {
                    return (max(Aleft, Bleft) + min(Aright, Bright)) / 2.0;
                }
                else {
                    return max(Aleft, Bleft);
                }
            }
            if (Aleft > Bright) {
                r = i - 1;
            }
            else {
                l = i + 1;
            }
        }

        return 0;
    }
};

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        deque<int>dq;
        vector<int>ans;
        //i is your right pointer
        for(int r=0;r<nums.size();r++){
            while(!dq.empty()&& dq.front()<=r-k){
                dq.pop_front();
            }
            //remove smaller elements
            while(!dq.empty() && nums[dq.back()]<=nums[r]){
                dq.pop_back();
            }
            dq.push_back(r);
            if(r>=k-1){
                ans.push_back(nums[dq.front()]);
            }
        }
        return ans;

    }
};

class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        if (!root) return {};

        queue<TreeNode*> q;
        q.push(root);

        vector<vector<int>> res;

        while (!q.empty()) {
            int n = q.size();
            vector<int> level;

            while (n--) {
                TreeNode* cur = q.front();
                q.pop();

                level.push_back(cur->val);

                if (cur->left) q.push(cur->left);
                if (cur->right) q.push(cur->right);
            }

            res.push_back(level);
        }

        return res;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<int> postorderTraversal(TreeNode* root) {
        if (!root) return {};
        TreeNode* cur=root;
        stack<TreeNode*>st;
        st.push(root);
        vector<int>res;
        while(!st.empty()){
            cur=st.top();
            st.pop();
            res.push_back(cur->val);
            if(cur->left)st.push(cur->left);
            if(cur->right)st.push(cur->right);

        }
        reverse(res.begin(),res.end());

        return res;

    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(null;ptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:

    void inorder(TreeNode* root,vector<int>&res){
        if(!root)return;//if node empty return void
        inorder(root->left, res); //left
        res.push_back(root->val);
        inorder(root->right,res);
    }
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int>res;
        stack<TreeNode*>st;

        TreeNode* cur=root;

        while(cur!=nullptr || !st.empty()){
            while(cur!=nullptr){//go left
                st.push(cur);
                cur=cur->left;
            }
            cur=st.top();
            st.pop();
            res.push_back(cur->val);
            cur=cur->right;
        }

        return res;
    }
};

class Solution {
public:
    int findTheCity(int n, vector<vector<int>>& edges, int distanceThreshold) {
        vector<vector<int>>adj(n,vector<int>(n,INT_MAX));

        for(auto e:edges){
            adj[e[0]][e[1]]=e[2];
            adj[e[1]][e[0]]=e[2];
        }
        for(int i=0;i<n;i++){
            adj[i][i]=0;
        }

        for(int k=0;k<n;k++){
            for(int i=0;i<n;i++){
                for(int j=0;j<n;j++){
                    if (adj[i][k] != INT_MAX && adj[k][j] != INT_MAX) {
                        adj[i][j] = min(adj[i][j], adj[i][k] + adj[k][j]);
                    }
                }
            }
        }

        int min_reach=INT_MAX;
        int ans=INT_MAX;
        for(int i=0;i<n;i++){
            int cnt=0;
            for(int j=0;j<n;j++){
                if(adj[i][j]<=distanceThreshold){
                    cnt++;
                }
            }
            if(cnt<=min_reach){
                ans=i;
                min_reach=cnt;
            }
        }
        return ans;

    }
};

class Solution {
public:
    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {
        vector<int>dist(n,INT_MAX);

        dist[src]=0;

        for(int i=0;i<=k;i++){
            vector<int>temp=dist;

            for(auto f:flights){
                int u=f[0],v=f[1],cost=f[2];
                if(dist[u]!=INT_MAX && dist[u]+cost<temp[v]){
                    temp[v]=dist[u]+cost;
                }
            }
            dist=temp;
        }

        return dist[dst]==INT_MAX ? -1: dist[dst];
    }
};

class Solution {
public:
    double maxProbability(int n, vector<vector<int>>& edges, vector<double>& succProb, int start_node, int end_node) {
        vector<vector<pair<int,double>>>adj(n);
        for(int i=0;i<succProb.size();i++){
            int u=edges[i][0];
            int v=edges[i][1];
            adj[u].push_back({v,succProb[i]});
            adj[v].push_back({u,succProb[i]});
        }

        priority_queue<pair<double,int>,vector<pair<double,int>>>pq;//prob,node
        pq.push({1,start_node});
        vector<double>prob(n,0);
        while(!pq.empty()){
            auto [p,node]=pq.top();
            pq.pop();

            if(p<prob[node])continue;

            for(auto v:adj[node]){
                //v is a pair
                auto u=v.first;
                auto prob_current=v.second;

                double new_prob=prob_current*p;
                if(new_prob>prob[u]){
                    prob[u]=new_prob;
                    pq.push({new_prob,u});
                }
            }
        }

        return prob[end_node];
    }
};

class Solution {
public:
    int minimumEffortPath(vector<vector<int>>& heights) {
        int dx[] = {1,-1,0,0};
        int dy[] = {0,0,1,-1};

        priority_queue<pair<int,pair<int,int>>,vector<pair<int,pair<int,int>>>,greater<>>pq;
        int n=heights.size();
        int m=heights[0].size();

        vector<vector<int>>dist(n,vector<int>(m,INT_MAX));
        dist[0][0]=0;
        pq.push({0,{0,0}});
        while(!pq.empty()){
            auto [d,node]=pq.top();
            pq.pop();
            int x=node.first;
            int y=node.second;

            if(d>dist[x][y])continue;

            for(int i=0;i<4;i++){
                int nx=x+dx[i];
                int ny=y+dy[i];
                if(nx<0||nx>=n||ny<0||ny>=m){
                    continue;
                }
                int new_d = max(d, abs(heights[x][y]-heights[nx][ny]));
                if(new_d<dist[nx][ny]){
                    dist[nx][ny]=new_d;
                    pq.push({new_d,{nx,ny}});
                }

            }
        }
        return dist[n-1][m-1];
    }
};

class Solution {
public:
    int networkDelayTime(vector<vector<int>>& times, int n, int k) {
        // Build adjacency list: node -> [(neighbor, weight), ...]
        vector<vector<pair<int,int>>> graph(n + 1);
        for (auto& t : times) {
            int u = t[0], v = t[1], w = t[2];
            graph[u].push_back({v, w});
        }

        // Min-heap of (distance, node)
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
        pq.push({0, k});

        vector<int> dist(n + 1, INT_MAX);
        dist[k] = 0;

        while (!pq.empty()) {
            auto [d, node] = pq.top();
            pq.pop();

            if (d > dist[node]) continue; // stale entry, skip

            for (auto& [neighbor, weight] : graph[node]) {
                int newDist = d + weight;
                if (newDist < dist[neighbor]) {
                    dist[neighbor] = newDist;
                    pq.push({newDist, neighbor});
                }
            }
        }

        int maxDist = 0;
        for (int i = 1; i <= n; i++) {
            if (dist[i] == INT_MAX) return -1; // unreachable node
            maxDist = max(maxDist, dist[i]);
        }

        return maxDist;
    }
};

class Solution {
public:
    struct DSU{
        int par[100100];
        int rank[100100];


        void init(int n){
            for(int i=0;i<n;i++){
                par[i]=i;
                rank[i]=0;
            }
        }

        int find(int x){
            if(par[x]==x)return x;
            else return par[x]=find(par[x]);
        }

        bool unite(int x,int y){
            int rootx=find(x);
            int rooty=find(y);
            if(rootx==rooty)return false;
            //rankx>ranky assumed
            if(rank[rootx]<rank[rooty])swap(rootx,rooty);
            if(rank[rootx]==rank[rooty]){
                rank[rootx]++;
            }
            par[rooty]=rootx;
            return true;
        }

    };
    int kruskal(int n,vector<vector<int>>&edges,int skip,int force){
        DSU dsu;
        dsu.init(n);

        int weight=0;
        int cnt=0;

        if(force!=-1){
            int u=edges[force][0];
            int v=edges[force][1];
            int w=edges[force][2];

            if(dsu.unite(u,v)){
            weight+=w;
            cnt++;
            }
        }
        for(int i=0;i<edges.size();i++){
            if(i==skip||i==force)continue;
            int u=edges[i][0];
            int v=edges[i][1];
            int w=edges[i][2];

            if(dsu.unite(u,v)){
                weight+=w;
                cnt++;
            }
        }
        if(cnt!=n-1)return INT_MAX;
        return weight;
    }
    vector<vector<int>> findCriticalAndPseudoCriticalEdges(int n, vector<vector<int>>& edges) {
        vector<vector<int>>ans(2);

        for(int i=0;i<edges.size();i++){
            edges[i].push_back(i);
            //storing the actual index of edges befor sorting
        }
        sort(edges.begin(),edges.end(),[](auto& a,auto& b){return a[2]<b[2];});
        int m=edges.size();
        int mst=kruskal(n,edges,-1,-1);
        for(int i=0;i<m;i++){
            int without=kruskal(n,edges,i,-1);//skip
            if(without>mst){
                //critical
                ans[0].push_back(edges[i][3]);//pushing the original index as answer
                continue;
            }
            int with=kruskal(n,edges,-1,i);
            if(with==mst){
                ans[1].push_back(edges[i][3]);
            }

        }
        return ans;
    }
};

