class Solution {
public:

    struct DSU{
        int par[100100];
        int rank[100100];

        void init(int n){
            for(int i=1;i<=n;i++){
                par[i]=i;
                rank[i]=1;//union by size
            }
        }

        int find(int x){
            if(par[x]==x)return x;
            else return (par[x]=find(par[x]));
        }

        int unite(int x,int y){
            int rootx=find(x);
            int rooty=find(y);

            if(rootx==rooty)return false;

            //by size

            //assume x>y
            if(rank[rootx]<rank[rooty])swap(rootx,rooty);

            rank[rootx]+=rank[rooty];//by size
            par[rooty]=rootx;
            return true;
        }
    };
    vector<int> findRedundantConnection(vector<vector<int>>& edges) {
        DSU dsu;
        int n=edges.size();
        dsu.init(n);

        for(auto e:edges){
            if(dsu.unite(e[0],e[1])==false){
                return e;
            }
        }
        return {};

    }
};

