    }
};

class Solution {
public:
    unsigned long long bitCount(unsigned long long num, int b) {
        if (b >= 63) return 0;  
        unsigned long long full = (num + 1) / (1ULL << (b + 1));
        unsigned long long rem = (num + 1) % (1ULL << (b + 1));
        return full * (1ULL << b) + (rem > (1ULL << b) ? rem - (1ULL << b) : 0);
    }

    unsigned long long accPrice(unsigned long long num, int x) {
        unsigned long long ans = 0;
        for (int b = x - 1; b < 63; b += x) {
            ans += bitCount(num, b);
        }
        return ans;
    }

    long long findMaximumNumber(long long k, int x) {
        unsigned long long low = 0, high = 1e18, ans = 0;
        while (low <= high) {
            unsigned long long mid = (low + high) / 2;
            if (accPrice(mid, x) <= (unsigned long long)k) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

