        // Case 1: Place tallest stick → visibility increases
        ans += rec(i + 1, visible + 1, n, k);    // 1 way (tallest at end)

        // Case 2: Place smaller stick → (n - 1 - i) choices to hide
        ans += (long long)(n - 1 - i) * rec(i + 1, visible, n, k);

        return dp[i][visible] = ans % MOD;
    }

    int rearrangeSticks(int n, int k) {
        memset(dp, -1, sizeof(dp));
        return rec(0, 0, n, k);
    }
};

